actions.script:
import groovy.json.JsonBuilder
import groovy.json.JsonSlurper
ec.message.clearAll()

Map args = (arguments instanceof Map) ? arguments : [:]

if (name == 'moqui_search_data_documents') {
    Map svcRes = ec.service.sync().name('mantle.GeneralServices.search#General').parameters(args).call()
    if (ec.message.hasError()) {
        String errText = ec.message.errorsString
        ec.message.clearErrors()
        result = [content: [[type: 'text', text: "Error: ${errText}"]], isError: true]
        return
    }
    Map payload = [
        documentList: svcRes.documentList ?: [],
        documentListCount: svcRes.documentListCount ?: 0,
        pageIndex: svcRes.documentListPageIndex,
        pageSize: svcRes.documentListPageSize
    ]
    result = [content: [[type: 'text', text: new JsonBuilder(payload).toString()]], isError: false]
    return
}

if (name == 'moqui_call_service') {
    String serviceName = args.serviceName as String
    Map serviceParameters = (args.parameters instanceof Map) ? (Map) args.parameters : [:]
    if (!serviceName) {
        result = [content: [[type: 'text', text: 'Error: serviceName is required']]], isError: true]
        return
    }
    Map svcRes = ec.service.sync().name(serviceName).parameters(serviceParameters).call()
    if (ec.message.hasError()) {
        String errText = ec.message.errorsString
        ec.message.clearErrors()
        result = [content: [[type: 'text', text: "Error: ${errText}"]], isError: true]
        return
    }
    result = [content: [[type: 'text', text: new JsonBuilder(svcRes).toString()]], isError: false]
    return
}

if (name == 'moqui_make_notification') {
    def nm = ec.makeNotificationMessage().topic(args.topic as String)
    if (args.subTopic) nm.subTopic(args.subTopic as String)
    if (args.userId) nm.userId(args.userId as String)
    if (args.userGroupId) nm.userGroupId(args.userGroupId as String)
    if (args.type) nm.type(args.type as String)
    if (args.title) nm.title(args.title as String)
    if (args.message instanceof Map) nm.message((Map) args.message)
    nm.send()
    result = [content: [[type: 'text', text: new JsonBuilder([status: 'sent', topic: args.topic]).toString()]], isError: false]
    return
}

def jsonSlurper = new JsonSlurper()
Map<String, Map> providerToolMappings = [:]
ec.entity.find('moqui.service.ServiceRegister').condition('serviceTypeEnumId', 'McpToolProvider').useCache(true).list()?.each { providerReg ->
    try {
        Map cfg = [:]
        if (providerReg.configParameters) cfg = (Map) jsonSlurper.parseText(providerReg.configParameters)
        String listServiceName = providerReg.serviceName
        String callServiceName = cfg.callServiceName ?: providerReg.serviceName
        Map providerRes = ec.service.sync().name(listServiceName).call()
        List providerTools = (providerRes?.toolList ?: providerRes?.tools ?: []) as List
        providerTools.each { Map toolDef ->
            if (toolDef?.name) providerToolMappings[toolDef.name as String] = [callServiceName: callServiceName]
        }
    } catch (Throwable t) {
        ec.logger.warn("Unable to load MCP tool provider ${providerReg.serviceRegisterId}: ${t.message}")
    }
}

Map providerEntry = providerToolMappings[name]
if (!providerEntry?.callServiceName) {
    result = [content: [[type: 'text', text: "Error: Unknown MCP tool ${name}"]], isError: true]
    return
}

Map providerCallParameters = [toolName: name, arguments: args]
Map providerResult = ec.service.sync().name(providerEntry.callServiceName as String).parameters(providerCallParameters).call()
if (ec.message.hasError()) {
    String errText = ec.message.errorsString
    ec.message.clearErrors()
    result = [content: [[type: 'text', text: "Error: ${errText}"]], isError: true]
    return
}
Map actualProviderResult = providerResult?.result ?: providerResult
result = (actualProviderResult instanceof Map && actualProviderResult.content instanceof List) ? actualProviderResult :
        [content: [[type: 'text', text: new JsonBuilder(actualProviderResult).toString()]], isError: false]

import java.net.URI
import java.net.URLDecoder
import groovy.json.JsonBuilder

Map<String, String> queryMap = [:]
URI parsedUri = new URI(uri)
if (parsedUri.query) {
    parsedUri.query.split('&').each { String pair ->
        List<String> kv = pair.split('=', 2) as List<String>
        String key = URLDecoder.decode(kv[0], 'UTF-8')
        String value = kv.size() > 1 ? URLDecoder.decode(kv[1], 'UTF-8') : ''
        queryMap[key] = value
    }
}

if (parsedUri.scheme == 'entity') {
    String entityName = parsedUri.host ?: parsedUri.schemeSpecificPart?.replaceFirst('^//', '')
    def entityDef = ec.entity.getEntityDefinition(entityName)
    List<Map> fieldList = []
    for (String fieldName in entityDef.getAllFieldNames()) {
        fieldList.add([name: fieldName, pk: entityDef.getPkFieldNames().contains(fieldName)])
    }
    List<Map> relationshipList = []
    entityDef.getRelationshipsInfo(false)?.each { relInfo ->
        relationshipList.add([
            name: relInfo.relationshipName,
            type: relInfo.type,
            relatedEntityName: relInfo.relatedEntityName,
            shortAlias: relInfo.shortAlias,
            title: relInfo.title
        ])
    }
    Map payload = [
        entityName: entityName,
        pkFieldNames: entityDef.getPkFieldNames(),
        fields: fieldList,
        relationships: relationshipList
    ]
    result = [resource: [uri: uri, mimeType: 'application/json', text: new JsonBuilder(payload).toString()]]
    return
}

if (parsedUri.scheme == 'record') {
    String entityName = parsedUri.host ?: parsedUri.schemeSpecificPart?.replaceFirst('^//', '')
    def find = ec.entity.find(entityName)
    queryMap.each { k, v -> find.condition(k, v) }
    Map record = find.one()
    result = [resource: [uri: uri, mimeType: 'application/json', text: new JsonBuilder(record ?: [:]).toString()]]
    return
}

if (parsedUri.scheme == 'datadocument') {
    String dataDocumentId = parsedUri.host ?: parsedUri.schemeSpecificPart?.replaceFirst('^//', '')
    Map dd = ec.entity.find('moqui.entity.document.DataDocument').condition('dataDocumentId', dataDocumentId).useCache(true).one()
    result = [resource: [uri: uri, mimeType: 'application/json', text: new JsonBuilder(dd ?: [:]).toString()]]
    return
}

ec.message.addError("Unsupported resource URI: ${uri}")

List<Map> promptList = []
for (Map wikiPage in (wikiPageList ?: [])) {
    promptList.add([
        name: wikiPage.pagePath,
        title: wikiPage.pagePath,
        description: "Wiki-backed MCP prompt ${wikiPage.pagePath}"
    ])
}
result = [prompts: promptList]
